void exact_outputs(const DaxaDepthReadback& a,const DaxaDepthReadback& b){
    auto exact=[](auto const& x,auto const& y){if(x.size()!=y.size())return false;for(size_t i=0;i<x.size();++i)if(std::bit_cast<uint32_t>(x[i])!=std::bit_cast<uint32_t>(y[i]))return false;return true;};
    check(exact(a.lr_disparity,b.lr_disparity)&&exact(a.lr_confidence,b.lr_confidence)&&a.lr_validity==b.lr_validity&&exact(a.depth,b.depth)&&exact(a.metric_confidence,b.metric_confidence)&&a.metric_validity==b.metric_validity&&a.provenance==b.provenance&&a.source_ids==b.source_ids&&a.age_ns==b.age_ns,"literal GPU LR/depth/metadata exact; no float tolerance");
}
